import pytest
from cart import apply_discount, bulk_discount_percent, parse_coupon, shipping_fee, Cart

# apply_discount
@pytest.mark.parametrize("price,percent,result",[
    (200,15,170.0),
    (100,0,100.0),
    (50,100,0.0),
])
def test_apply_discount(price,percent,result):
    assert apply_discount(price,percent)==result

@pytest.mark.parametrize("price,percent",[
    (-1,10),(50,-5),(50,101)
])
def test_apply_discount_errors(price,percent):
    with pytest.raises(ValueError):
        apply_discount(price,percent)

# bulk_discount_percent
@pytest.mark.parametrize("quantity,result",[ (9,0),(10,5),(49,5),(50,10),(99,10),(100,15) ])
def test_bulk_discount(quantity,result):
    assert bulk_discount_percent(quantity)==result

@pytest.mark.parametrize("quantity",[-1,0,2.5])
def test_bulk_discount_errors(quantity):
    with pytest.raises(ValueError):
        bulk_discount_percent(quantity)

# parse_coupon
@pytest.mark.parametrize("code,result",[
    ("SAVE10",10),("save20",20),(" SAVE30 ",30),
])
def test_parse_coupon(code,result):
    assert parse_coupon(code)==result

@pytest.mark.parametrize("code",["SAVEX","SAVE0","SAVE51","SAVE-5","X10"," " ])
def test_parse_coupon_error(code):
    with pytest.raises(ValueError):
        parse_coupon(code)

# shipping_fee
@pytest.mark.parametrize("subtotal,member,result",[
    (1000,False,0),(1001,True,30),(500,False,60),(300,True,30)
])
def test_shipping_fee(subtotal,member,result):
    assert shipping_fee(subtotal,member)==result

@pytest.mark.parametrize("subtotal",[-5,-10])
def test_shipping_fee_error(subtotal):
    with pytest.raises(ValueError):
        shipping_fee(subtotal,False)

# Cart operations
@pytest.fixture
def cart():
    return Cart()

def test_add_and_items(cart):
    cart.add_item("apple",10,3)
    cart.add_item("banana",5,2)
    assert cart.items()=={"apple":3,"banana":2}
    # adding existing increases quantity and must match price
    cart.add_item("apple",10,1)
    assert cart.items()["apple"]==4
    with pytest.raises(ValueError):
        cart.add_item("apple",12,1)

def test_remove_item(cart):
    cart.add_item("orange",8,5)
    cart.remove_item("orange",3)
    assert cart.items()["orange"]=2
    cart.remove_item("orange",2)
    assert "orange" not in cart.items()
    with pytest.raises(KeyError):
        cart.remove_item("pear",1)

def test_subtotal(cart):
    # apple 10 each, qty 5 => bulk discount 5% -> 10*5*0.95=47.5
    cart.add_item("apple",10,5)
    assert cart.subtotal()==47.5
    # add banana 2 each qty1 no discount
    cart.add_item("banana",2,1)
    assert cart.subtotal()==49.5

def test_total(cart):
    cart.add_item("item",100,10)  # bulk 5% -> 950
    # total without coupon member False: subtotal 950, shipping 60 =>1010
    assert cart.total(member=False)==1010.0
    # member True shipping 30 =>980
    assert cart.total(member=True)==980.0
    # with valid coupon SAVE10 (10%) discount before shipping
    expected = round(950*0.9 + 60,2)
    assert cart.total(coupon="SAVE10")==expected
    # invalid coupon raises ValueError
    with pytest.raises(ValueError):
        cart.total(coupon="BADCODE")

